flags.typeql:
match
$d isa person, has born_in $bi;
$bi like ".*Nebraska.*";
directed (director: $d, film: $m);
acted_in (actor: $a, film: $m);
$a has name $name;
select $name;
distinct;
sort $name;
limit 5;
fetch {
  "name": $name
};

match
$u isa user, has name "John";
$rel isa rated (user: $u, film: $m);
$rel has rating $r;
reduce $avg_rating = mean($r) groupby $m;
sort $avg_rating desc;
limit 5;
fetch {
  "title": $m.title,
  "avgRating": $avg_rating
};

match
$m isa movie, has languages $l;
$l like ".*English.*";
$l like ".*French.*";
in_genre (film: $m, genre: $g);
$g has name $n;
select $n;
distinct;
limit 3;
fetch { "name": $n };

match
$u isa user;
$m isa movie;
$r isa rated (user: $u, film: $m);
$r has timestamp $t;
sort $t asc;
limit 3;
fetch {
  "MovieTitle": $m.title,
  "ReleaseDate": $m.released
};

match
$m isa movie;
rated (user: $u, film: $m);
$u isa user;
located_in (resident: $u, country: $c);
$c has name $cn;
select $m, $cn;
distinct;
reduce $country_count = count groupby $m;
match $country_count > 5;
$m has title $t;
sort $country_count desc;
limit 5;
fetch { "MovieTitle": $t, "NumberOfCountries": $country_count };

match
