with fun oldest_year() -> integer:
  match $m isa movie, has year $y;
  return min($y);
with fun newest_year() -> integer:
  match $m isa movie, has year $y;
  return max($y);
match
  $user isa user;
  let $min_year = oldest_year();
  let $max_year = newest_year();
  $old_movie isa movie, has year $oy;
  $oy == $min_year;
  $new_movie isa movie, has year $ny;
  $ny == $max_year;
  rated (user: $user, film: $old_movie);
  rated (user: $user, film: $new_movie);
limit 3;
fetch { "userName": $user.n

