with fun movie_count($a: person) -> integer:
    match acted_in (actor: $a, film: $m);
    return count;
match
    $a isa person;
    acted_in (actor: $a, film: $m);
    $m has imdb_rating $r;
let $mc = movie_count($a);
match $mc > 3;
reduce $avg_rating = mean($r) groupby $a;
sort $avg_rating asc;
limit 3;
fetch { "actorName": $a.name, "avgRating": $avg_rating };

with fun directed_count($p: person) -> integer:
  match directed (director: $p, film: $m);
  return count;
with fun acted_count($p: person) -> integer:
  match acted_in (actor: $p, film: $m);
  return count;
match
  $p isa person;
  directed (director: $p, film: $m);
  $m has imdb_rating $r;
  let $dc = directed_count($p);
  let $ac = acted_count($p);
  $dc <= $ac;
sort $r desc;
limit 5;
fetch { "MovieTitle": $m.title, "Rating": $r };

