with fun user_genre_count($u: user) -> integer:
  match
    rated (user: $u, film: $m);
    in_genre (film: $m, genre: $g);
  select $g;
  distinct;
  return count;
match
  $u isa user;
  $g isa genre;
reduce $total_genres = count($g) groupby $u;
match
  let $user_genres = user_genre_count($u);
  $user_genres == $total_genres;
sort $user_genres desc;
limit 3;
fetch { "userName": $u.name, "genresRatedCount": $user_genres };

